def dfs_order(graph, start):
    if not graph:
        return []
    seen = set()
    order = []
    def visit(vertex):
        seen.add(vertex)
        order.append(vertex)
        for neighbor in graph[vertex]:
            if neighbor not in seen:
                visit(neighbor)
    visit(start)
    return order

print(dfs_order({'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': [], 'E': []}, 'A'))
print(dfs_order({'A': ['B'], 'B': ['A']}, 'A'))
print(dfs_order({}, None))

def can_reach(graph, start, goal):
    if not graph:
        return False
    seen = {start}
    stack = [start]
    while stack:
        vertex = stack.pop()
        if vertex == goal:
            return True
        for neighbor in graph[vertex]:
            if neighbor not in seen:
                seen.add(neighbor)
                stack.append(neighbor)
    return False

print(can_reach({'A': ['B'], 'B': ['A'], 'C': []}, 'A', 'C'))
print(can_reach({'A': []}, 'A', 'A'))
print(can_reach({'A': ['B', 'B'], 'B': []}, 'A', 'B'))
print(can_reach({}, None, None))

def dfs_forest(graph):
    seen = set()
    groups = []
    def visit(vertex, group):
        seen.add(vertex)
        group.append(vertex)
        for neighbor in graph[vertex]:
            if neighbor not in seen:
                visit(neighbor, group)
    for vertex in graph:
        if vertex not in seen:
            group = []
            visit(vertex, group)
            groups.append(group)
    return groups

print(dfs_forest({'A': ['B'], 'B': [], 'C': []}))
print(dfs_forest({'A': [], 'B': ['A']}))
print(dfs_forest({}))

def dfs_allowed(graph, start, blocked):
    if not graph or start in blocked:
        return []
    seen = set(blocked)
    order = []
    def visit(vertex):
        seen.add(vertex)
        order.append(vertex)
        for neighbor in graph[vertex]:
            if neighbor not in seen:
                visit(neighbor)
    visit(start)
    return order

print(dfs_allowed({'A': ['B', 'C'], 'B': ['D'], 'C': [], 'D': []}, 'A', {'B'}))
print(dfs_allowed({'A': []}, 'A', {'A'}))
print(dfs_allowed({}, None, set()))
